const emoPut=e=>{const i=$('#mi');if(i){i.value+=e;i.focus()}},selCh=i=>{T.ch=i;T.sq='';T.rp=0;T.mp='chat';render()},mdl=(k,x)=>{const s=cs();T.md={k,x,t:'ov',r:k=='settings'&&s&&s.roles.length?0:-1};render()},cmd=()=>{T.md=0;render()},sv_=()=>{save();render()},chTab=t=>{T.md.t=t;render()};
