const chPriv=(k,ci)=>{const s=cs();if(!has(s,'channels'))return;const c=k=='v'?s.vc[ci]:s.ch[ci],o=c.ov['@everyone']=c.ov['@everyone']||{};if(o.view===-1)delete o.view;else o.view=-1;if(!Object.keys(o).length)delete c.ov['@everyone'];sv_()};
