const srvName=v=>{const s=cs();if(has(s,'server')&&v.trim()){s.name=v.trim();sv_()}},srvLogo=rm=>{const s=cs();if(!has(s,'server'))return;rm?(s.logo='',sv_()):pick(d=>{s.logo=d;sv_()})},delS=()=>{if(confirm('Delete this server?')){DB.servers=DB.servers.filter(x=>x!=cs());T.md=0;sv_()}},leaveS=()=>{const s=cs();if(confirm('Leave this server?')){delete s.mem[DB.cur];T.md=0;sv_()}};
/* roles */
const selRole=i=>{T.md.r=i;render()},newRole=()=>{const s=cs();if(!has(s,'roles'))return;let n='new role',k=1;while(s.roles.some(r=>r.n==n))n='new role '+ ++k;s.roles.push({n,color:'#99aab5',p:[]});T.md.r=s.roles.length-1;sv_()};
function roleSet(i,k,v){const s=cs(),r=s.roles[i];if(!r||!has(s,'roles'))return;const o=r.n;if(k=='n'){v=cleanN(v);if(!v||v=='@everyone'||s.roles.some((x,j)=>j!=i&&x.n==v)){alert('Role name must be unique');return render()}Object.keys(s.mem).forEach(u=>{s.mem[u]=s.mem[u].map(n=>n==o?v:n)});[...s.ch,...s.vc].forEach(c=>{if(c.ov[o]){c.ov[v]=c.ov[o];delete c.ov[o]}})}r[k]=v;sv_()}
const rolePerm=(i,p,on_)=>{const s=cs();if(!has(s,'roles'))return;const r=i<0?s.ev:s.roles[i];r.p=r.p.filter(x=>x!=p);if(on_)r.p.push(p);save();chatRefresh()};
const roleMove=(i,d)=>{const s=cs(),j=i+d;if(!has(s,'roles')||j<0||j>=s.roles.length)return;[s.roles[i],s.roles[j]]=[s.roles[j],s.roles[i]];T.md.r=j;sv_()};
const roleDel=i=>{const s=cs(),r=s.roles[i];if(!r||!has(s,'roles')||!confirm('Delete role "'+r.n+'"?'))return;Object.keys(s.mem).forEach(u=>{s.mem[u]=s.mem[u].filter(n=>n!=r.n)});[...s.ch,...s.vc].forEach(c=>delete c.ov[r.n]);s.roles.splice(i,1);T.md.r=-1;sv_()};
const addRole=(u,i)=>{const s=cs(),r=s.roles[+i];if(!r||!has(s,'roles'))return;if(!s.mem[u].includes(r.n))s.mem[u].push(r.n);sv_()},delRoleFrom=(u,i)=>{const s=cs(),r=s.roles[i];if(!r||!has(s,'roles'))return;s.mem[u]=s.mem[u].filter(x=>x!=r.n);sv_()},kickM=u=>{const s=cs();if(has(s,'kick')&&u!=s.owner&&confirm('Kick @'+u+'?')){delete s.mem[u];sv_()}};
const tri=(k,ci,ri,p,cur)=>`<span class=tri><button class="dn ${cur===-1?'on':''}" onclick="chOv('${k}',${ci},${ri},'${p}',-1)" title=Deny>✕</button><button class="nt ${cur==null?'on':''}" onclick="chOv('${k}',${ci},${ri},'${p}',0)" title=Inherit>∕</button><button class="up ${cur===1?'on':''}" onclick="chOv('${k}',${ci},${ri},'${p}',1)" title=Allow>✓</button></span>`;
function modal(){const m=T.md;if(!m)return'';const k=m.k;
if(k=='inv'){const s=byInv(m.x);return`<div class="ov dm"><div class=ct>${s?`<div class=ivic>${s.logo?`<img src="${s.logo}">`:esc(s.name[0].toUpperCase())}</div><div class=mu>You've been invited to join a server</div><h2 style="margin:6px 0">${esc(s.name)}</h2><div class=mu><i class=dg1></i>${Object.keys(s.mem).filter(u=>stOf(u)!='offline').length} Online &nbsp; <i class="dg1 gr"></i>${Object.keys(s.mem).length} Members</div><button class=pb onclick=acceptInv()>${s.mem[DB.cur]?'Continue to Server':'Accept Invite'}</button><button class=g onclick=declInv()>No Thanks</button>`:`<h2>Invite Invalid</h2><p class=mu>This invite may have expired, or the server lives on a different device or browser.</p><button class=pb onclick=declInv()>Continue</button>`}</div></div>`}
if(k=='status')return`<div class="ov dm" onclick="if(event.target==this)cmd()"><div class=mn>${[['online','Online','#23a559'],['idle','Idle','#f0b232'],['dnd','Do Not Disturb','#f23f43'],['invisible','Invisible','#80848e']].map(([a,l,c])=>`<div onclick="setSt('${a}')"><i class=dot style="background:${c}"></i> ${l}</div>`).join('')}</div></div>`;
const s=cs();let b='';
if(k=='addsrv')b=`<h2>Create a server</h2><input id=sn placeholder="Server name"><button onclick="mkS($('#sn').value)">Create</button><h3>Have an invite already?</h3><input id=jc placeholder="Invite link or code"><button class=g onclick="joinS($('#jc').value)">Join Server</button>`;
else if(k=='menu'){const n=Object.keys(s.mem).length,o=Object.keys(s.mem).filter(u=>stOf(u)!='offline').length;b=`<div class=mn><div class="mu mh"><b style="color:#fff">${esc(s.name)}</b><br><i class=dg1></i>${o} Online <i class="dg1 gr"></i>${n} Member${n==1?'':'s'}</div>${has(s,'invite')?`<div onclick="mdl('invite')">Invite People</div>`:''}${has(s,'server')||has(s,'roles')||has(s,'kick')?`<div onclick="mdl('settings',has(s,'server')?'ov':has(s,'roles')?'rl':'mb')">Server Settings</div>`:''}${has(s,'channels')?`<div onclick="mdl('newch','0')">Create Channel</div><div onclick="mdl('newcat')">Create Category</div>`:''}<div style="color:#f23f43" onclick="${s.owner==DB.cur?'delS()':'leaveS()'}">${s.owner==DB.cur?'Delete Server':'Leave Server'}</div></div>`}
else if(k=='newch')b=`<h2>Create Channel</h2><label class=lb>Channel type</label><select id=ct><option value=t>Text</option><option value=v ${m.x=='v'?'selected':''}>Voice</option></select><label class="lb w">Category</label><select id=cc>${cats(s).map((c,i)=>`<option value=${i} ${String(m.x)==String(i)?'selected':''}>${esc(c)}</option>`).join('')}</select><label class="lb w">Channel name</label><input id=cn placeholder=new-channel><button onclick=mkCh()>Create Channel</button>`;
else if(k=='newcat')b=`<h2>Create Category</h2><input id=cn placeholder="Category name"><button onclick=mkCat()>Create Category</button>`;
else if(k=='chset'||k=='vset'){const vv=k=='vset',c=vv?s.vc[m.x]:s.ch[m.x],t=m.t||'ov',ri=m.r,kk=vv?'v':'t';
if(c){b=`<div class=stg><div class=sn><b class=mu>${vv?'🔊':'#'} ${esc(c.n).toUpperCase()}</b><div class="sti ${t=='ov'?'on':''}" onclick="chTab('ov')">Overview</div><div class="sti ${t=='pm'?'on':''}" onclick="chTab('pm')">Permissions</div></div><div class=sc2>`;
if(t=='ov')b+=`<h3>Overview</h3><label class=lb>Channel name</label><input value="${esc(c.n)}" onchange="chRen('${kk}',${m.x},this.value)"><button class=g style="color:#f23f43;margin-top:10px" onclick="chDel('${kk}',${m.x})">Delete channel</button>`;
else{const priv=(c.ov['@everyone']||{}).view===-1,rows=vv?[['view','View Channel'],['connect','Connect']]:[['view','View Channel'],['send','Send Messages'],['attach','Attach Files']],key=ri<0?'@everyone':(s.roles[ri]||{}).n,o=c.ov[key]||{};
b+=`<h3>Permissions</h3><label class=pr><span><b>Private channel</b><div class=s>Only members with a role that allows it (and admins) can see this channel.</div></span><input type=checkbox class=sw ${priv?'checked':''} onchange="chPriv('${kk}',${m.x})"></label><div class=rlw><div class=rll>${[{n:'@everyone',color:'#99aab5'},...s.roles].map((x,i)=>`<div class="sti ${i-1==ri?'on':''}" onclick="selRole(${i-1})"><i class=dot style="background:${x.color||'#99aab5'}"></i>${esc(x.n)}</div>`).join('')}</div><div class=rle><p class=s>Permissions for <b>${esc(key)}</b> in this channel: ✕ deny · ∕ use role default · ✓ allow</p>${rows.map(([p,l])=>`<div class=pr><span>${l}</span>${tri(kk,m.x,ri,p,o[p])}</div>`).join('')}</div></div>`}
b+='</div></div>'}}
else if(k=='invite'){const fr=F(me()).fr.filter(f=>U(f)).slice(0,8);b=`<h2>Invite friends to ${esc(s.name)}</h2><div class=mu style="margin:6px 0 16px">${ic('hash',16)} ${esc(curCh(s).n)}</div>${invCard(invLink(s)&&s.inv)}${fr.length?`<label class=lb style="color:#b5bac1;margin-top:14px">Invite friends</label>${fr.map(f=>`<div class=fr>${av(f,32)}<div>${esc(nm(f))}</div><button class="${(T.sent||{})[f]?'g':''}" onclick="dmInvite('${f}')">${(T.sent||{})[f]?'Sent':'Invite'}</button></div>`).join('')}`:''}<label class=lb style="color:#b5bac1;margin-top:14px">Or, send a server invite link to a friend</label><div class=ivl><input id=ivi readonly value="${esc(invLink(s))}" onclick=this.select()><button id=ivb onclick=copyInv()>Copy</button></div><button class=g style="margin-top:8px" onclick=sendInv()>Send link to #${esc(curCh(s).n)}</button><p class=s>Your invite link never expires.</p>`}
else if(k=='settings'){const t=m.x||'ov',ri=m.r,tab=(id,l,o)=>o?`<div class="sti ${t==id?'on':''}" onclick="mdl('settings','${id}')">${l}</div>`:'';
b=`<div class=stg><div class=sn><b class=mu>${esc(s.name).toUpperCase()}</b>${tab('ov','Overview',has(s,'server'))}${tab('rl','Roles',has(s,'roles'))}${tab('mb','Members',has(s,'roles')||has(s,'kick'))}</div><div class=sc2>`;
if(t=='ov')b+=`<h3>Server Overview</h3><label class=lb>Server name</label><input value="${esc(s.name)}" onchange="srvName(this.value)"><div class=row style="margin-top:10px">${s.logo?`<img class=lg src="${s.logo}">`:''}<span><button class=g onclick=srvLogo()>Change icon</button>${s.logo?'<button class=g onclick="srvLogo(1)">Remove</button>':''}</span></div>`;
if(t=='rl'){const A=[{n:'@everyone',color:'#99aab5',p:s.ev.p,ev:1},...s.roles],cu=A[ri+1]||A[0];
b+=`<div class=row><h3 style="margin:0">Roles</h3><button onclick=newRole()>+ Create Role</button></div><p class=s>Roles give members a color and permissions. Roles higher in the list win. Set per-channel permissions with the ⚙ next to a channel.</p><div class=rlw><div class=rll>${A.map((x,i)=>`<div class="sti ${i-1==ri?'on':''}" onclick="selRole(${i-1})"><i class=dot style="background:${x.color||'#99aab5'}"></i><span style="flex:1">${esc(x.n)}</span>${i-1==ri&&i>0?`<span onclick="event.stopPropagation();roleMove(${ri},-1)">▲</span><span onclick="event.stopPropagation();roleMove(${ri},1)">▼</span>`:''}</div>`).join('')}</div><div class=rle>`;
if(!cu.ev)b+=`<label class=lb>Role name</label><input value="${esc(cu.n)}" onchange="roleSet(${ri},'n',this.value)"><label class="lb w">Role color</label><div class=sws>${COLORS.map(c=>`<i style="background:${c}" class="${c==cu.color?'on':''}" onclick="roleSet(${ri},'color','${c}')"></i>`).join('')}<input type=color value="${cu.color||'#99aab5'}" onchange="roleSet(${ri},'color',this.value)"></div>`;
b+=`<label class="lb w">Permissions${cu.ev?' (everyone)':''}</label>${PM.map(([p,l,d])=>`<label class=pr><span><b>${l}</b><div class=s>${d}</div></span><input type=checkbox class=sw ${cu.p.includes(p)?'checked':''} onchange="rolePerm(${ri},'${p}',this.checked)"></label>`).join('')}`;
if(!cu.ev)b+=`<button class=g style="color:#f23f43;margin-top:10px" onclick=roleDel(${ri})>Delete role</button>`;b+='</div></div>'}
if(t=='mb')b+=`<h3>Members — ${Object.keys(s.mem).length}</h3>${Object.keys(s.mem).map(u=>`<div class=fr>${av(u,34)}<div>${esc(nm(u))}${u==s.owner?' 👑':''}<br><small class=mu>@${u}</small><div class=chips2>${s.mem[u].map(n=>{const i=s.roles.findIndex(r=>r.n==n),r=s.roles[i];return r?`<span class=chip><i class=dot style="background:${r.color}"></i>${esc(n)}${has(s,'roles')?`<b onclick="delRoleFrom('${u}',${i})">✕</b>`:''}</span>`:''}).join('')}${has(s,'roles')?`<select onchange="addRole('${u}',this.value)"><option value="">+ Role</option>${s.roles.map((r,i)=>s.mem[u].includes(r.n)?'':`<option value="${i}">${esc(r.n)}</option>`).join('')}</select>`:''}</div></div>${has(s,'kick')&&u!=s.owner&&u!=DB.cur?`<button class=g onclick="kickM('${u}')">Kick</button>`:''}</div>`).join('')}`;
b+='</div></div>'}
return`<div class="ov dm" onclick="if(event.target==this)cmd()"><div>${b}<p class=ct><button class=g onclick=cmd()>Close</button></p></div></div>`}

/* ---- TikTok-style shorts ---- */
const raH=s=>`<div onclick="vp('${s.u}')">${av(s.u,52)}<small>View Profile</small></div><div onclick=flk(${s.id})>${ic('heart',32,s.l.includes(DB.cur)?'#ff3b5c':'none')}<small>${s.l.length}</small></div><div onclick=fcm(${s.id})>${ic('dots',32)}<small>${s.c.length}</small></div><div onclick=sh(${s.id})>${ic('share',32)}<small>Share</small></div>`;
const updS=id=>{const s=S_(id);document.querySelectorAll(`.sv[data-id="${id}"]`).forEach(e=>{e.querySelector('.ra').innerHTML=raH(s);e.querySelector('.cap').innerHTML=capH(s)})},flk=id=>{const s=S_(id),i=s.l.indexOf(DB.cur);i<0?s.l.push(DB.cur):s.l.splice(i,1);save();updS(id)},fcm=id=>openCm(id);
/* ---- profiles ---- */
const flw=k=>Object.keys(DB.users).filter(x=>(U(x).following||[]).includes(k)),posts=k=>DB.shorts.filter(s=>s.u==k&&((U(k)||{}).media||[]).some(m=>m.id==s.mid));
function pstats(k){const u=U(k),P=posts(k),mine=k==DB.cur,fo=(me().following||[]).includes(k);return`<div class=pf><div class=ct>${av(k,84)}<h2 style="margin:8px 0 0">${esc(u.name)}</h2><div class=mu>@${k}</div></div><div class=pst><div><b>${P.length}</b><span>Posts</span></div><div><b>${flw(k).length}</b><span>Followers</span></div><div><b>${(u.following||[]).length}</b><span>Following</span></div></div>${mine?'':`<div class=ct><button onclick="tfol('${k}')">${fo?'Unfollow':'Follow'}</button><button class=g onclick="addFr('${k}')">Add friend</button><button class=g onclick="openDm('${k}')">Message</button></div>`}<h3>Videos</h3><div class=gl>${P.map(s=>`<div onclick="T.vw=${s.id};render()">${thumb(((U(k)||{}).media||[]).find(m=>m.id==s.mid))}</div>`).join('')||'<p class=mu>No videos yet</p>'}</div></div>`}
const tfol=k=>{const a=me();a.following=a.following||[];const i=a.following.indexOf(k);i<0?a.following.push(k):a.following.splice(i,1);sv_()},addFr=k=>{const t=F(me());if(t.fr.includes(k))return alert('@'+k+' is already your friend');if(t.out.includes(k))return alert('Request already sent');fadd(k);alert('Friend request sent')};
const uprofile=()=>U(T.pu)?`<button class=bk onclick="go(T.pv&&T.pv!='uprofile'?T.pv:'shorts')">${ic('chev',16)} Back</button>`+pstats(T.pu):'<p class=mu>User not found</p>';
const vwV=()=>{const s=S_(T.vw),m=s&&((U(s.u)||{}).media||[]).find(m=>m.id==s.mid);return`<div class=ov onclick="if(event.target==this){T.vw=0;render()}"><div class=ct>${m?med(m):''}<p>${s?esc(s.cap):''}</p><button class=g onclick="T.vw=0;render()">Close</button></div></div>`};
function attach3d(){const c=$('#bd3');if(!c||!(window.Board3D&&Board3D.ok()))return;Board3D.onSquare=cl;Board3D.mount(c);Board3D.sync(G)}
/* ---- storage: "server" (node server.js: saved on disk and shared) or "local" (saved in this browser) ---- */
const SM={mode:'local'},MU={},EMPTY=()=>({users:{},shorts:[],servers:[],leagues:[],clans:[],dms:{}});
let saveT=0;
function save(){const j=JSON.stringify(DB);try{localStorage.setItem(SM.mode=='server'?'major_srv':'major',j)}catch(e){if(SM.mode!='server')toast('Storage is full — download a backup in Settings')}if(SM.mode=='server'){clearTimeout(saveT);saveT=setTimeout(pushDB,100)}}
const dbOut=()=>{const o={...DB};delete o.cur;return o};
function pushDB(){fetch('api/db',{method:'PUT',headers:{'Content-Type':'application/json','X-Client':TID},body:JSON.stringify(dbOut())}).catch(()=>toast('Game server not reachable — changes were not saved'))}
const api=(p,b)=>fetch('api/'+p,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}).then(r=>r.json()).catch(()=>({ok:false,err:'Server not reachable'}));
const idb=()=>new Promise((res,rej)=>{if(!window.indexedDB)return rej(new Error('no idb'));const r=indexedDB.open('clashboard',1);r.onupgradeneeded=()=>r.result.createObjectStore('media');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
const idbTx=(mode,f)=>idb().then(d=>new Promise((res,rej)=>{const t=d.transaction('media',mode),q=f(t.objectStore('media'));t.oncomplete=()=>res(q&&q.result);t.onerror=()=>rej(t.error)}));
const idbPut=(id,b)=>idbTx('readwrite',s=>s.put(b,String(id))),idbGet=id=>idbTx('readonly',s=>s.get(String(id))),idbDel=id=>idbTx('readwrite',s=>s.delete(String(id)));
async function idbLoad(){try{const d=await idb();await new Promise(res=>{const q=d.transaction('media').objectStore('media').openCursor();q.onsuccess=()=>{const c=q.result;if(c){MU[c.key]=URL.createObjectURL(c.value);c.continue()}else res()};q.onerror=()=>res()})}catch(e){}}
const mURL=id=>SM.mode=='server'?'media/'+id:(MU[String(id)]||''),mu_=m=>m.src||mURL(m.id);
async function putMedia(id,blob){id=String(id);if(SM.mode=='server'){const r=await fetch('media/'+id,{method:'PUT',headers:{'Content-Type':blob.type||'application/octet-stream'},body:blob});if(!r.ok)throw new Error('upload failed');return}MU[id]=URL.createObjectURL(blob);try{await idbPut(id,blob)}catch(e){toast('Could not save the file permanently on this device')}}
async function rmMedia(id){id=String(id);if(SM.mode=='server'){fetch('media/'+id,{method:'DELETE'}).catch(()=>{});return}if(MU[id]){try{URL.revokeObjectURL(MU[id])}catch(e){}delete MU[id]}try{await idbDel(id)}catch(e){}}
const refd=id=>DB.shorts.some(s=>s.mid==id)||DB.servers.some(s=>s.ch.some(c=>c.m.some(x=>x.md&&x.md.id==id)))||Object.values(DB.dms||{}).some(L=>L.some(x=>x.md&&x.md.id==id));
async function addM(type,src){try{const blob=typeof src=='string'?await(await fetch(src)).blob():src,id=Date.now().toString(36)+Math.random().toString(36).slice(2,6);await putMedia(id,blob);me().media.unshift({id,type,mime:blob.type});save();toast('Saved to Photo App');if(V=='photos')render()}catch(e){toast('Could not save the file')}}
const delM=async i=>{const m=me().media[i];if(!m)return;me().media.splice(i,1);DB.shorts=DB.shorts.filter(s=>s.mid!=m.id);if(!refd(m.id))await rmMedia(m.id);save();render()};
const med=m=>!m?'<span class=s>(removed)</span>':!mu_(m)?'<span class=s>(loading…)</span>':m.type=='img'?`<img src="${mu_(m)}">`:`<video src="${mu_(m)}" controls></video>`;
const thumb=m=>!m||!mu_(m)?'':m.type=='img'?`<img src="${mu_(m)}">`:`<video src="${mu_(m)}" muted preload=metadata></video>`;
async function migrateMedia(){let ch=0;const d2b=async s=>(await fetch(s)).blob();
for(const k in DB.users)for(const m of (DB.users[k].media||[]))if(m.src){try{const b=await d2b(m.src);await putMedia(m.id,b);m.mime=b.type;delete m.src;ch=1}catch(e){}}
for(const s of DB.servers)for(const c of s.ch)for(const x of c.m||[])if(x.md&&x.md.src){try{const b=await d2b(x.md.src),id='m'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);await putMedia(id,b);x.md={id,type:x.md.type};ch=1}catch(e){}}
if(ch)save()}
const need=new Set();function loadMissing(){for(const k in DB.users)for(const m of (DB.users[k].media||[])){const id=String(m.id);if(!MU[id]&&!need.has(id)){need.add(id);idbGet(id).then(b=>{if(b){MU[id]=URL.createObjectURL(b);if(['photos','uprofile'].includes(V))render()}}).catch(()=>{})}}}
async function storeInit(){
try{const c=new AbortController(),t=setTimeout(()=>c.abort(),1500),r=await fetch('api/db',{signal:c.signal,cache:'no-store'});clearTimeout(t);
if(r.ok&&r.headers.get('X-Clash')=='1'){const d=await r.json(),cur=DB.cur;SM.mode='server';DB=Object.assign(EMPTY(),d);DB.cur=DB.users[cur]?cur:null;if(!DB.cur)try{sessionStorage.removeItem('cur')}catch(e){}V=DB.cur?'home':'login'}}catch(e){}
if(SM.mode=='local')await idbLoad();DB.dms=DB.dms||{};normAll();await migrateMedia();try{navigator.storage&&navigator.storage.persist&&navigator.storage.persist()}catch(e){}}
