/* ---- backup (single-browser mode) ---- */
async function bkp(){if(SM.mode=='server')return toast('Your data is saved in the "data" folder next to server.js — copy that folder to back it up');toast('Preparing backup…');const media={},ids=new Set();for(const k in DB.users)(DB.users[k].media||[]).forEach(m=>ids.add(String(m.id)));
for(const id of ids){try{if(MU[id]){const b=await(await fetch(MU[id])).blob();media[id]={t:b.type,d:await new Promise(r=>{const f=new FileReader;f.onload=()=>r(f.result);f.readAsDataURL(b)})}}}catch(e){}}
const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({v:1,db:DB,media})],{type:'application/json'}));a.download='clash-board-backup.json';a.click();toast('Backup downloaded')}
function rst(){if(SM.mode=='server')return toast('Restore is only for single-browser mode');const i=document.createElement('input');i.type='file';i.accept='.json';i.onchange=async()=>{try{const o=JSON.parse(await i.files[0].text());if(!o.db||!o.db.users)throw 0;if(!confirm('Replace ALL data in this browser with the backup?'))return;const cur=DB.cur;DB=Object.assign(EMPTY(),o.db);DB.cur=DB.users[cur]?cur:null;for(const id in o.media||{}){const b=await(await fetch(o.media[id].d)).blob();await putMedia(id,b)}normAll();save();toast('Backup restored');V=DB.cur?'home':'login';render()}catch(e){toast('That is not a valid backup file')}};i.click()}
const settings=()=>`${back}<h2 class=h2>Setting</h2><div class=ls><div class=li onclick="go('profile')">${ic('user',24)}<span>Edit profile</span>${ic('chev',18)}</div><div class=li onclick="T.tut=1;render()">${ic('play',24)}<span>How to play</span>${ic('chev',18)}</div><div class=li onclick=bkp()>${ic('image',24)}<span>Download backup</span>${ic('chev',18)}</div><div class=li onclick=rst()>${ic('users',24)}<span>Restore backup</span>${ic('chev',18)}</div><div class=li onclick=logout()>${ic('lock',24)}<span>Log out</span>${ic('chev',18)}</div></div><p class=s>${SM.mode=='server'?'Saved on the game server (data folder) and shared with everyone using it.':'Saved in this browser only. Run node server.js to save on disk and share with other people.'}</p>`;
/* ---- tutorial (shown after sign up, also under Settings and Home) ---- */
const NAMEP={K:'King',S:'Soldier',G:'General',M:'Major',C:'Captain (Castle)'};
function svgBoard(b,marks,sz=17){let o=`<svg viewBox="0 0 ${11*sz} ${9*sz}" class=dg>`;for(let r=8;r>=0;r--)for(let c=0;c<11;c++){if(!ok(c,r))continue;const x=c*sz,y=(8-r)*sz,cx=x+sz/2,cy=y+sz/2,m=marks&&marks.find(m=>m.x==c&&m.y==r),p=b[r][c];o+=`<rect x="${x}" y="${y}" width="${sz}" height="${sz}" fill="${(c+r)%2?'#a68b5b':'#eadfc8'}"/>`;if(m)o+=p?`<circle cx="${cx}" cy="${cy}" r="${sz*.46}" fill="none" stroke="${m.only?'#f0c020':'#2fb344'}" stroke-width="2"/>`:`<circle cx="${cx}" cy="${cy}" r="${sz*.22}" fill="${m.only?'#f0c020':'#2fb344'}"/>`;if(p)o+=`<circle cx="${cx}" cy="${cy}" r="${sz*.38}" fill="${p.c=='w'?'#f4a6c0':'#7b4fb0'}"/><text x="${cx}" y="${cy+sz*.14}" font-size="${sz*.42}" text-anchor="middle" fill="${p.c=='w'?'#400':'#fff'}" font-weight="700">${p.t}</text>`}return o+'</svg>'}
function pieceDiag(t){const b=Array.from({length:9},()=>Array(11).fill(null));b[4][5]={t,c:'w'};if(t=='S')[[4,3],[6,3],[4,5],[6,5]].forEach(([c,r])=>{b[r][c]={t:'S',c:'b'}});return`<div class=dgc>${svgBoard(b,mv(b,5,4))}<div class=s>${NAMEP[t]}</div></div>`}
const TUT=[
{t:'Welcome to Clash Board!',b:'<p>Clash Board is a strategy game for two players on a cross-shaped board of 75 squares.</p><p><b>Goal: checkmate the enemy King</b> — trap it so it cannot escape capture. You play <b>White</b> (pink here) at the bottom, and White always moves first.</p>',d:'start'},
{t:'Making a move',b:'<p><b>1.</b> Tap one of your pieces — it lifts up and <b>green dots</b> show where it can go.<br><b>2.</b> Tap a square to move there. Tap an enemy piece on a dot to capture it.<br><b>3.</b> A character sitting at the table picks the piece up and moves it for you.</p><p>Drag to rotate the camera, scroll or pinch to zoom, and use <b>Table view</b> / <b>Board view</b> under the board.</p>'},
{t:'King and Soldier',b:'<p><b>King</b> — one square in any of the 8 directions. Keep it safe!</p><p><b>Soldier</b> — one square up, down, left or right (even backwards). It can only <b>capture</b> diagonally (yellow rings).</p>',d:['K','S']},
{t:'General and Major',b:'<p><b>General</b> — slides any distance up, down, left or right, and steps 1 square diagonally.</p><p><b>Major</b> — slides any distance diagonally, and steps 1 square up, down, left or right.</p>',d:['G','M']},
{t:'Captain (Castle)',b:'<p><b>Captain</b> — jumps exactly 2 squares straight up, straight down or diagonally. It is the only piece that can jump over other pieces.</p>',d:['C']},
{t:'Check, mate and draws',b:'<p><b>Check</b>: your King is attacked — you must escape. You can never make a move that leaves your own King in danger.</p><p><b>Checkmate</b> wins. <b>Stalemate</b> (no legal move while not in check) counts as a <b>loss</b>. If only Kings are left, it is a draw.</p>'},
{t:'Timer and promotion',b:'<p>You have <b>20 seconds</b> per move. Run out of time 3 times in a match and you lose.</p><p>When a Soldier reaches the enemy back rank, pick <b>one</b> reward: bring back one of your lost pieces, or remove any enemy piece (not the King). Each reward can be used once per match.</p>'}];
const tutV=()=>{const i=Math.min(T.tut,TUT.length)-1,s=TUT[i],last=i==TUT.length-1;return`<div class="ov dm"><div class=tut><div class=row><b class=mu>Tutorial ${i+1} / ${TUT.length}</b><span class=lk onclick=tutEnd()>Skip</span></div><h2 style="margin:8px 0">${s.t}</h2>${s.d=='start'?`<div class=dgc>${svgBoard(newB())}<div class=s>Starting position — your pieces are pink at the bottom</div></div>`:Array.isArray(s.d)?`<div class=dgs>${s.d.map(pieceDiag).join('')}</div>`:''}<div class=tb2>${s.b}</div><div class=row><button class=g ${i?'':'disabled'} onclick="T.tut=${Math.max(1,i)};render()">Back</button>${last?`<span><button onclick=tutEnd()>Got it</button><button class=g onclick="tutEnd();play(1)">Practice vs Bot</button></span>`:`<button onclick="T.tut=${i+2};render()">Next</button>`}</div><div class=dots>${TUT.map((_,j)=>`<i class="${j==i?'on':''}"></i>`).join('')}</div></div></div>`};
