const ago=ts=>{const d=(Date.now()-ts)/1000;return d<60?'now':d<3600?Math.floor(d/60)+'m':d<86400?Math.floor(d/3600)+'h':Math.floor(d/86400)+'d'};
const shorts=()=>`<div class=shw><div class=shh><span class=tabs><b class="${T.ft=='fl'?'':'on'}" onclick="T.ft='fy';render()">For You</b><b class="${T.ft=='fl'?'on':''}" onclick="T.ft='fl';render()">Following</b></span><button onclick=post()>+ Post</button></div><div class=feed id=feed></div></div>`;
function initFeed(){const f=$('#feed');if(!f)return;const fl=T.ft=='fl',all=()=>DB.shorts.map(s=>({s,m:((U(s.u)||{}).media||[]).find(m=>m.id==s.mid)})).filter(x=>x.m&&mu_(x.m)&&(!fl||(me().following||[]).includes(x.s.u)));
if(!all().length){f.innerHTML=`<p class="mu ct" style="padding:90px 24px;color:#ccc">${fl?'Nobody to show yet. Follow people from their profile (tap View Profile on a video) to see their videos here.':'No videos yet. Record a match (⋮ menu on Home), then tap + Post.'}</p>`;return}
const io=window.IntersectionObserver?new IntersectionObserver(es=>es.forEach(e=>{const v=e.target.querySelector('video');if(!v)return;if(e.isIntersecting&&e.intersectionRatio>=.6)v.play().catch(()=>{});else v.pause()}),{root:f,threshold:[.6]}):null;
const add=()=>{f.insertAdjacentHTML('beforeend',all().sort(()=>Math.random()-.5).map(x=>svItem(x.s,x.m)).join(''));f.querySelectorAll('.sv:not([data-o])').forEach(e=>{e.dataset.o=1;io&&io.observe(e)})};
f.onclick=e=>{if(e.target.tagName=='VIDEO')e.target.paused?e.target.play():e.target.pause()};f.onscroll=()=>{if(f.scrollTop+f.clientHeight*2>f.scrollHeight)add()};add();if(f.scrollHeight<f.clientHeight*3)add()}
const svItem=(s,m)=>`<div class=sv data-id=${s.id}>${m.type=='img'?`<img src="${mu_(m)}">`:`<video src="${mu_(m)}" loop playsinline muted preload=metadata></video>`}<div class=ra>${raH(s)}</div><div class=cap>${capH(s)}</div><div class=dc></div></div>`;
const capH=s=>`<b>@${esc(s.u)}</b><br>${esc(s.cap)}`;
const cmItem=(s,c)=>`<div class=cmi2>${av(c.u,34)}<div class=cmb><div><b>${esc(nm(c.u))}</b> <span class=mu>${c.ts?ago(c.ts):''}</span></div><div class=cmt>${esc(c.t)}</div><div class=cma><span onclick="cmReply('${c.u}')">Reply</span>${c.u==DB.cur||s.u==DB.cur?`<span onclick="cmDel(${s.id},${c.id})">Delete</span>`:''}</div></div><div class=cml2 onclick="cmLike(${s.id},${c.id})">${ic('heart',18,(c.l||[]).includes(DB.cur)?'#ff3b5c':'none')}<small>${(c.l||[]).length||''}</small></div></div>`;
function openCm(id){const w=$('.shw');if(!w)return;if(!$('#cms'))w.insertAdjacentHTML('beforeend','<div class=cms id=cms></div>');T.cm=id;cmRe();setTimeout(()=>{const i=$('#cmt');i&&i.focus()},60)}
function cmRe(){const s=S_(T.cm),e=$('#cms');if(!s||!e)return;s.c.forEach((c,i)=>{c.id=c.id||Date.now()+i;c.l=c.l||[]});const keep=($('#cmt')||{}).value||'';e.innerHTML=`<div class=cmh><b>${s.c.length} comment${s.c.length==1?'':'s'}</b><span onclick=closeCm()>✕</span></div><div class=cml>${s.c.map(c=>cmItem(s,c)).join('')||'<p class="mu ct" style="padding:30px">No comments yet. Be the first!</p>'}</div><div class=cmin><input id=cmt maxlength=300 placeholder="Add a comment…" onkeydown="if(event.key==='Enter')cmSend()"><button onclick=cmSend()>Send</button></div>`;$('#cmt').value=keep;const l=$('.cml');l.scrollTop=l.scrollHeight}
const closeCm=()=>{const e=$('#cms');if(e)e.remove();T.cm=0},cmSend=()=>{const i=$('#cmt'),t=i.value.trim().slice(0,300);if(!t)return;const s=S_(T.cm);s.c.push({id:Date.now(),u:DB.cur,t,ts:Date.now(),l:[]});save();cmRe();$('#cmt').focus();updS(s.id)},cmLike=(sid,cid)=>{const c=S_(sid).c.find(x=>x.id==cid),i=c.l.indexOf(DB.cur);i<0?c.l.push(DB.cur):c.l.splice(i,1);save();cmRe()},cmDel=(sid,cid)=>{const s=S_(sid);s.c=s.c.filter(x=>x.id!=cid);save();cmRe();updS(sid)},cmReply=u=>{const i=$('#cmt');i.value='@'+u+' '+i.value;i.focus()};

